import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"氢等离子体与镜面","description":"","frontmatter":{"title":"氢等离子体与镜面","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/hydrogen-plasma-mirrors.md","filePath":"litho/hydrogen-plasma-mirrors.md","lastUpdated":1789023840000}'),E={name:"litho/hydrogen-plasma-mirrors.md"};function B(m,a,c,_,u,A){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="氢等离子体与镜面" tabindex="-1">氢等离子体与镜面 <a class="header-anchor" href="#氢等离子体与镜面" aria-label="Permalink to &quot;氢等离子体与镜面&quot;">​</a></h1><div class="epigraph"><p>EUV 把氢气解离成自由基和离子。它们刻锡、也溅射帽层。镜面活在等离子体边缘，不是活在中性缓冲里。</p><footer>—— 据 Bakshi 污染与氢化学；ASML 对氢环境光学的公开讨论</footer></div><p><a href="/litho/euv-illumination-settings">上一课</a>把光瞳足迹铺到镜子上。缺口是足迹所在的气体：氢不只是 DGL 的窗帘，在 EUV 照射下就是低密度等离子体。真空分区如何把碳和水挡在合同外，留给<a href="/litho/euv-vacuum-contamination">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/euv-hydrogen-dgl">DGL</a> 写的是差压气帘和 SnH₄ 通道。进阶缺口是等离子体–表面：光子、二次电子把 H₂ 解离、电离，镜面同时承受 H 自由基化学、H⁺ 溅射和紫外辅助解吸。钌帽要在「允许刻锡」和「自身不被剥蚀、不起泡」之间工作。照明设置改变局部功率密度，等离子体密度和帽层温度跟着走，同一张膜在极子热点上先坏。</p><p>缺口不是再画气锁缝，而是把镜面当成等离子体壁。只谈中性氢流量，会低估离子溅射和氢植入导致的起泡（blistering）。</p><p><span class="marginnote">这不是刻蚀机里的高密度氢等离子体。分压低、电离度低，但 EUV 光子能量高，表面反应仍然快。不要用 ICP 刻蚀速率外推。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>材料：帽层选 Ru 等，因为对氢相对惰、对锡可被下游化学清。基底和多层硅仍怕氧化和互扩散，帽必须连续。工艺：控氢分压、电子温度代理量（功率、辅助解离）和镜温。计量：反射率、应力、氢含量、表面形貌（起泡、粗化）。收集镜处于更浓的等离子体，策略是可洗可换；投影镜等离子体更稀，策略是材料清单和放气控制，避免把扫描腔变成第二光源舱。</p><p>与照明耦合：高 PFR 边缘极子把功率堆在镜子特定环带，局部氢化学加速。换设置等于换损伤地图，资格认证要带功率和气体，不能只做可见光外观。</p><h3 id="帽层是等离子体壁材料" tabindex="-1">帽层是等离子体壁材料 <a class="header-anchor" href="#帽层是等离子体壁材料" aria-label="Permalink to &quot;帽层是等离子体壁材料&quot;">​</a></h3><p>钌的资格不是「镀得上」，而是在目标氢分压、离子通量和温度下溅射率与起泡潜伏期可接受。换帽材料等于换清洗终点：更抗氢的帽可能更难刻锡。收集镜与投影镜、掩模的帽配方可以不同，因为等离子体密度差一个量级。不能用投影镜的氢窗口去规定光源舱流量。</p>',12)),(e(),n(p,null,{default:r(()=>[h(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20EUV%5B%22EUV%20%E5%85%89%E5%AD%90%22%5D%20--%3E%20DIS%5B%22H2%20%E8%A7%A3%E7%A6%BB%20%2F%20%E7%94%B5%E7%A6%BB%22%5D%0A%20%20DIS%20--%3E%20ETCH%5B%22H%20%E5%88%BB%20Sn%20%2F%20C%22%5D%0A%20%20DIS%20--%3E%20SP%5B%22%E7%A6%BB%E5%AD%90%E6%BA%85%E5%B0%84%E5%B8%BD%E5%B1%82%22%5D%0A%20%20DIS%20--%3E%20BL%5B%22%E6%B0%A2%E6%A4%8D%E5%85%A5%E8%B5%B7%E6%B3%A1%22%5D%0A%20%20ETCH%20--%3E%20R%5B%22R%20%E5%8F%AF%E7%BB%B4%E6%8C%81%22%5D%0A%20%20SP%20--%3E%20MSFR%5B%22MSFR%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20BL%20--%3E%20MSFR%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自由基刻蚀是希望的通道。离子把动量交给表面，溅射产额随能量和入射角变，正入射多层的帽层会被慢慢减薄，周期和应力漂移。氢原子扩散进膜，在缺陷处复合成 H₂，气泡把多层顶起——这是不可逆 MSFR。Madey、Bajt 等对 EUV 光学表面化学的工作，把碳生长、氧化和氢损伤写成竞争反应：缺氢则碳化，氢过则溅射/起泡。</p><p><span class="marginnote">「开氢就能洗」只覆盖化学可逆项。等离子体壁效应把清洗课的不可逆清单具体化到离子和起泡。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把整机真空材料清单写完，下一课才谈碳氢放气、水汽和分区泵。不重写收集镜更换流程。出处：Bakshi 氢与表面；Bajt / Madey EUV 表面化学；ASML 氢环境光学；DGL 与清洗课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EUV + H₂ 在镜面附近是等离子体，自由基、离子和植入同时存在。</li><li>照明足迹决定损伤地图；帽层化学必须兼容刻锡与抗起泡。</li><li>下一课把视角拉到整机真空与污染物种。</li><li>出处：Bakshi；Bajt、Madey；ASML。</li></ul>',7))])}const D=o(E,[["render",B]]);export{f as __pageData,D as default};
